css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .58); position: relative; overflow: hidden; }
.loader span { position: absolute; height: 17%; border-radius: 3px; background: linear-gradient(color-mix(in srgb, #fff 18%, var(--accent)), var(--accent)); box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent-2) 55%, transparent); transform-origin: 50% 100%; animation: brick-set calc(var(--loader-speed) * 3.2) cubic-bezier(.4, 0, .5, 1) infinite; }
.loader span:nth-of-type(1) { left: 2%; bottom: 6%; width: 30%; }
.loader span:nth-of-type(2) { left: 35%; bottom: 6%; width: 30%; animation-delay: calc(var(--loader-speed) * .28); }
.loader span:nth-of-type(3) { left: 68%; bottom: 6%; width: 30%; animation-delay: calc(var(--loader-speed) * .56); }
.loader span:nth-of-type(4) { left: 2%; bottom: 29%; width: 14%; animation-delay: calc(var(--loader-speed) * .84); }
.loader span:nth-of-type(5) { left: 19%; bottom: 29%; width: 30%; animation-delay: calc(var(--loader-speed) * 1.12); }
.loader span:nth-of-type(6) { left: 52%; bottom: 29%; width: 30%; animation-delay: calc(var(--loader-speed) * 1.4); }
.loader span:nth-of-type(7) { left: 85%; bottom: 29%; width: 13%; animation-delay: calc(var(--loader-speed) * 1.68); }
.loader span:nth-of-type(8) { left: 2%; bottom: 52%; width: 30%; animation-delay: calc(var(--loader-speed) * 1.96); }
.loader span:nth-of-type(9) { left: 35%; bottom: 52%; width: 30%; animation-delay: calc(var(--loader-speed) * 2.24); }
.loader .trowel { position: absolute; right: 4%; top: 4%; width: 18%; height: 22%; background: linear-gradient(#e2e8f0, #94a3b8); clip-path: polygon(0 0, 100% 22%, 60% 100%); animation: brick-trowel calc(var(--loader-speed) * .8) ease-in-out infinite; }
@keyframes brick-set { 0%, 4% { transform: translateY(-260%) rotate(-8deg); opacity: 0; } 12%, 78% { transform: translateY(0) rotate(0deg); opacity: 1; } 92%, 100% { transform: translateY(0) rotate(0deg); opacity: 0; } }
@keyframes brick-trowel { 0%, 100% { transform: rotate(-10deg) translateY(0); } 50% { transform: rotate(6deg) translateY(12%); } }
